import sys
import heapq

def run(lines):
    slots = []  # list of [generation, occupied, bytearray]
    free_heap = []
    out = []

    def is_live(i, g):
        return 0 <= i < len(slots) and slots[i][1] and slots[i][0] == g

    for line in lines:
        parts = line.split()
        if not parts:
            continue
        cmd = parts[0]
        if cmd == "new":
            s = int(parts[1])
            if free_heap:
                i = heapq.heappop(free_heap)
                slots[i][0] += 1
                slots[i][1] = True
                slots[i][2] = bytearray(s)
            else:
                i = len(slots)
                slots.append([1, True, bytearray(s)])
            out.append(f"h {i} {slots[i][0]}")
        elif cmd == "set":
            i, g, off, v = int(parts[1]), int(parts[2]), int(parts[3]), int(parts[4])
            if not is_live(i, g):
                out.append("stale")
            elif off >= len(slots[i][2]):
                out.append("bounds")
            else:
                slots[i][2][off] = v
                out.append("ok")
        elif cmd == "sum":
            i, g = int(parts[1]), int(parts[2])
            if not is_live(i, g):
                out.append("stale")
            else:
                out.append(str(sum(slots[i][2])))
        elif cmd == "move":
            i, gi, j, gj = int(parts[1]), int(parts[2]), int(parts[3]), int(parts[4])
            if not is_live(i, gi) or not is_live(j, gj):
                out.append("stale")
            elif i == j:
                out.append("same")
            else:
                slots[j][2].extend(slots[i][2])
                slots[i][1] = False
                slots[i][2] = bytearray()
                heapq.heappush(free_heap, i)
                out.append(f"ok {len(slots[j][2])}")
        elif cmd == "free":
            i, g = int(parts[1]), int(parts[2])
            if not is_live(i, g):
                out.append("stale")
            else:
                slots[i][1] = False
                slots[i][2] = bytearray()
                heapq.heappush(free_heap, i)
                out.append("ok")

    live_l = 0
    live_b = 0
    for s in slots:
        if s[1]:
            live_l += 1
            live_b += len(s[2])
    out.append(f"live {live_l} {live_b}")
    return "\n".join(out) + "\n"

if __name__ == "__main__":
    lines = sys.stdin.read().splitlines()
    sys.stdout.write(run(lines))
